GROUP BY a.year,a.month,a.day

SELECT s.*,@rownum := @rownum + 1 AS 'ranking' FROM (
SELECT a.device_code,SUM(a.today_all) AS 'total', warning_source,SUM(a.real_num) AS 'realNum' FROM
vm_statistics_event_num_day a

AND DATE_FORMAT(a.create_date,'%Y-%m-%d') >= #{startDate}
AND DATE_FORMAT(a.create_date,'%Y-%m-%d') <= #{endDate}


        AND a.province_id = #{areaCode}


        AND a.city_id = #{areaCode}


        AND a.county_id = #{areaCode}


AND a.device_code != '' AND a.device_code IS NOT NULL
AND a.today_all != 0 AND a.today_all IS NOT NULL
    ${dataScope}

GROUP BY a.device_code
ORDER BY



            SUM(a.today_all)


            SUM(a.real_num)




            desc,


            asc,


            desc,



SUM(a.today_all) DESC
LIMIT 10
) s,(SELECT @rownum := 0) t

