    ${dataScope}

SELECT bb.typeId,bb.typeName,cc.assigned_date as 'eventDate' FROM (SELECT DISTINCT ala.type_value 'typeId',ala.type_name 'typeName' FROM sys_alarm_type ala
AND ala.type_value IN
#{item}
) bb, (SELECT date_format(assigned_date,'%Y-%m-%d') assigned_date FROM (SELECT adddate('2022-01-01',t3.i*1000 + t2.i*100 + t1.i*10 + t0.i) assigned_date FROM (select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t0, (select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t1, (select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t2, (select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t3 ) c WHERE assigned_date between SUBSTR(#{vo.startTime},1,10) and #{vo.endTime}) cc
ORDER BY cc.assigned_date,FIELD(bb.typeId,
#{item} ) ASC

SELECT
    a.tenant_id AS 'tenantId',
    a.industry_code AS 'industryCode',
    SUM( a.plot_area_sum ) AS 'plotAreaSum'
FROM
    vm_statistics_event_plot_area a


        AND a.tenant_id = #{tenantId}


        AND a.industry_code = #{industryCode}


        AND (a.province_id = #{areaCode} OR a.city_id = #{areaCode} OR a.county_id = #{areaCode})


        AND DATE_FORMAT(create_date, '%Y-%m-%d') = #{date}

    ${dataScope}
